-- BC-0101 V1: identity, catalog and provenance tables (PRD 6.1, ADR-0002,
-- planning/06-first-two-sprints.md section 1).
--
-- Conventions
--   * Primary keys are UUIDv7 generated by the application (ADR-0002), so no DB defaults.
--   * All timestamps are timestamptz; the API normalises to UTC on output (ADR-0002).
--   * Flyway runs as beacon_migrate, which owns schema public. beacon_app receives
--     SELECT/INSERT/UPDATE/DELETE through the default privileges set in
--     infra/compose/postgres/init.sql, so no GRANT is needed here.
--   * routes.provider / boards.provider and provenance_sources.source are free text so a
--     later user-defined wall or `user-photo` provider fits without a schema change
--     (planning/00-execution-master-plan.md section 7b).
--   * Additions beyond the section-1 excerpt (consent scopes/text hash, board synthetic flag,
--     geometry and angles, route tags) are pulled forward from contract v1.1 / threat model
--     TM-09 / C-07 so later tickets do not need an ALTER.

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------
CREATE TABLE users (
  id            uuid PRIMARY KEY,
  username      text NOT NULL UNIQUE,
  password_hash text NOT NULL,
  role          text NOT NULL DEFAULT 'USER'
                CHECK (role IN ('USER', 'ADMIN')),
  status        text NOT NULL DEFAULT 'ACTIVE'
                CHECK (status IN ('ACTIVE', 'DELETION_PENDING', 'DELETED')),
  created_at    timestamptz NOT NULL DEFAULT now(),
  deleted_at    timestamptz
);
COMMENT ON TABLE users IS
  'Pseudonymous local accounts (PRD 6.1 users, ADR-0002 erasure marks deleted_at)';

CREATE TABLE consents (
  id              uuid PRIMARY KEY,
  user_id         uuid NOT NULL REFERENCES users (id),
  consent_version text NOT NULL,
  scopes_json     jsonb NOT NULL DEFAULT '{"service": true, "research": false}',
  text_sha256     char(64),
  consented_at    timestamptz NOT NULL,
  revoked_at      timestamptz,
  UNIQUE (user_id, consent_version)
);
COMMENT ON TABLE consents IS
  'Versioned, revocable consent records keyed per user and version (PRD 6.1, threat model TM-09 upsert key, C-07 scopes and text hash)';

CREATE TABLE user_preferences (
  user_id               uuid PRIMARY KEY REFERENCES users (id),
  board_id              text NOT NULL,
  angle_deg             smallint NOT NULL,
  initial_grade_band    text NOT NULL,
  goals_json            jsonb NOT NULL DEFAULT '[]',
  privacy_settings_json jsonb NOT NULL DEFAULT '{}',
  updated_at            timestamptz NOT NULL
);
COMMENT ON TABLE user_preferences IS
  'Onboarding preferences, one row per user (PRD 6.1 user_preferences)';

-- ---------------------------------------------------------------------------
-- Provenance
-- ---------------------------------------------------------------------------
CREATE TABLE provenance_sources (
  provenance_id         uuid PRIMARY KEY,
  source                text NOT NULL,
  version               text,
  content_sha256        char(64) NOT NULL UNIQUE,
  synthetic             boolean NOT NULL,
  license_review_status text NOT NULL
                        CHECK (license_review_status IN
                               ('SYNTHETIC', 'LOCAL_RESEARCH_ONLY', 'REVIEWED_PERMITTED')),
  imported_at           timestamptz NOT NULL
);
COMMENT ON TABLE provenance_sources IS
  'Origin, content hash and license review state of every imported catalog file (PRD 6.1 provenance_sources, ADR-0002)';

-- ---------------------------------------------------------------------------
-- Catalog
-- ---------------------------------------------------------------------------
CREATE TABLE boards (
  board_id              text PRIMARY KEY,
  provider              text NOT NULL,
  layout_id             text NOT NULL,
  size_id               text NOT NULL,
  canonical_config_json jsonb NOT NULL,
  synthetic             boolean NOT NULL,
  geometry_json         jsonb NOT NULL DEFAULT '{}',
  available_angles_json jsonb NOT NULL DEFAULT '[]',
  provenance_id         uuid NOT NULL REFERENCES provenance_sources (provenance_id)
);
COMMENT ON TABLE boards IS
  'Board or wall definitions including user-defined walls, with geometry units and available angles (PRD 6.1 boards, master plan 7b)';

CREATE TABLE holds (
  hold_id            uuid PRIMARY KEY,
  board_id           text NOT NULL REFERENCES boards (board_id),
  provider_hold_id   text NOT NULL,
  x                  numeric(8, 3) NOT NULL,
  y                  numeric(8, 3) NOT NULL,
  geometry_meta_json jsonb,
  UNIQUE (board_id, provider_hold_id)
);
COMMENT ON TABLE holds IS
  'Hold positions per board in board geometry units (PRD 6.1 holds)';
-- holds(board_id) lookups are served by the leading column of the UNIQUE index above.

CREATE TABLE routes (
  route_id            uuid PRIMARY KEY,
  board_id            text NOT NULL REFERENCES boards (board_id),
  provider_route_uuid text NOT NULL,
  canonical_version   int NOT NULL DEFAULT 1,
  name                text,
  setter_pseudonym    text,
  tags_json           jsonb NOT NULL DEFAULT '[]',
  active_from         timestamptz,
  active_to           timestamptz,
  provenance_id       uuid NOT NULL REFERENCES provenance_sources (provenance_id),
  UNIQUE (board_id, provider_route_uuid)
);
COMMENT ON TABLE routes IS
  'Angle-independent route identity per board with provenance (PRD 6.1 routes)';
-- routes(board_id) and routes(board_id, provider_route_uuid) lookups are served by the
-- UNIQUE index above, so no separate routes_board_idx is created.

CREATE TABLE route_variants (
  variant_id              uuid PRIMARY KEY,
  route_id                uuid NOT NULL REFERENCES routes (route_id),
  angle_deg               smallint NOT NULL,
  grade_numeric           numeric(5, 2),
  grade_observation_count int NOT NULL DEFAULT 0,
  validation_status       text NOT NULL DEFAULT 'ACTIVE'
                          CHECK (validation_status IN ('ACTIVE', 'RETIRED', 'INVALID')),
  UNIQUE (route_id, angle_deg)
);
COMMENT ON TABLE route_variants IS
  'Route at one angle, the unit that is graded, attempted and recommended (PRD 6.1 route_variants, ADR-0002 public id provider_route_uuid:angle_deg)';
-- route_variants(route_id) lookups are served by the leading column of the UNIQUE index above.

CREATE TABLE route_placements (
  variant_id      uuid NOT NULL REFERENCES route_variants (variant_id),
  hold_id         uuid NOT NULL REFERENCES holds (hold_id),
  role            text NOT NULL
                  CHECK (role IN ('START', 'HAND', 'FOOT', 'FINISH')),
  placement_order int,
  PRIMARY KEY (variant_id, hold_id, role)
);
COMMENT ON TABLE route_placements IS
  'Hold roles per route variant so per-angle placement differences stay representable (PRD 6.1 route_placements)';

-- ---------------------------------------------------------------------------
-- Indexes for catalog queries
-- ---------------------------------------------------------------------------
-- Explore / list filters active variants by angle and grade range (board filter joins routes).
CREATE INDEX route_variants_search_idx
  ON route_variants (angle_deg, grade_numeric, variant_id)
  WHERE validation_status = 'ACTIVE';

-- Reverse lookup: which variants use a hold (hold_id is not a leading PK column).
CREATE INDEX route_placements_hold_idx ON route_placements (hold_id);
